using System.Linq;
using Newtonsoft.Json.Linq;
using UnityEngine;
namespace CastleFight {
public sealed partial class HumanMatch {
    public const float NightStarfallHitLife=3.3f; // Native StarfallTarget Birth, effect_models.json
    public sealed class NightZone {public int id,team;public Vector2 point,caster;public float age,next=2;}
    public readonly List<NightZone> NightZones=new List<NightZone>();public readonly int[] MoonshineCharges=new int[2];
    public int NightGrants,NightRoots,NightStarfalls,NightBarrages,NightBlessings;
    bool NightFighter(Unit u,int team)=>u!=null&&u.hp>0&&u.team==team&&!Hidden(u)&&!Invulnerable(u)&&!ElementalIllusion(u)&&Lines[u.kind].unit!="YTct";
    Unit[] NightTargets(int team,Vector2 at,JToken cfg){string kind=(string)cfg["kind"];if(kind=="night_moonshine")return Array.Empty<Unit>();if(kind=="night_grant")return Units.Where(u=>u.hp>0&&u.team==team&&((string)Lines[u.kind].stats["unit_types"]??"").ToLowerInvariant().Contains("sapper")&&!u.abilities.Contains("A08C")).ToArray();if(kind=="night_starfall")return Units.Where(u=>NatureEligible(u,team)).ToArray();return Units.Where(u=>Valid(u,team,cfg,false)&&!IsNagaHero(u)&&Vector2.Distance(u.position,at)<=F(cfg,"range")).ToArray();}
    public bool CastNightBuilding(Hut h,string id,int suggested=-1){var cfg=Abilities[id];if(h==null||!Huts.Contains(h)||!h.paid||h.hp<=0||h.paused||BuildingDisabled(h)>0||cfg==null||!Lines[h.kind].abilities.Contains(id)||h.mana<F(cfg,"mana")||h.spellTimers.TryGetValue(id,out float wait)&&wait>0)return false;string kind=(string)cfg["kind"];var targets=NightTargets(h.team,h.position,cfg);if(kind!="night_moonshine"&&targets.Length==0)return false;var target=targets.FirstOrDefault(u=>u.id==suggested)??(targets.Length==0?null:targets[Mathf.Min(targets.Length-1,(int)(Roll()*targets.Length))]);if(kind=="night_moonshine"){MoonshineCharges[h.team]++;PulseAt(h.position,1,Color.magenta,"Лунный заряд",1,"night:moonshine_ready:effect");}else if(kind=="night_grant"){foreach(string child in new[]{"A08C","A08D","A08F"})Grant(target,child);NightGrants++;PulseAt(h.position,1,Color.magenta,"",1,"night:night_grant_caster:effect");PulseAt(target.position,1,Color.magenta,"",1,"night:night_grant_target:effect");}else if(kind=="night_starfall"){NightZones.Add(new NightZone{id=nextId++,team=h.team,point=target.position,caster=h.position});NightStarfalls++;}else return false;h.mana-=F(cfg,"mana");h.spellTimers[id]=BuildingCooldown(h,F(cfg,"cd"));h.attackSerial++;h.attackPoseLeft=.5f;SpellsCast++;return true;}
    void TickNightBuilding(Hut h){foreach(string id in Lines[h.kind].abilities)if(new[]{"night_moonshine","night_grant","night_starfall"}.Contains((string)Abilities[id]?["kind"])&&(!h.spellTimers.TryGetValue(id,out float wait)||wait<=0))h.spellTimers[id]=CastNightBuilding(h,id)?BuildingCooldown(h,F(Abilities[id],"cd")):.25f;}
    bool CastNightRoots(Unit source,JToken cfg,Unit suggested){var targets=NightTargets(source.team,source.position,cfg);if(targets.Length==0)return false;var target=targets.Contains(suggested)?suggested:targets[Mathf.Min(targets.Length-1,(int)(Roll()*targets.Length))];var child=(JObject)Abilities[(string)cfg["effect_id"]];int count=(int)F(cfg,"count",1);var victims=count==1?new[]{target}:Units.Where(u=>NatureEligible(u,source.team)&&!Flying(u)&&Vector2.Distance(u.position,target.position)<=10).OrderBy(u=>u.effects.Any(e=>(string)e.config?["code"]=="AEer")?1:0).Take(count).ToArray();foreach(var u in victims)if(Valid(u,source.team,child,false)){ApplyEffectData(u,child,source.team);PulseAt(u.position,1,Color.green,"Корни",F(child,"duration"),"night:"+(string)child["id"]+":buff");}NightRoots++;return true;}
    public void NightOnAttacked(Unit victim){if(victim==null||victim.hp<=0||Invulnerable(victim)||victim.abilities.Contains("A08H")||MoonshineCharges[victim.team]<=0||!((string)Lines[victim.kind].stats["unit_types"]??"").ToLowerInvariant().Contains("sapper"))return;MoonshineCharges[victim.team]--;var cfg=Abilities["A08A"];foreach(var u in Units)if(Valid(u,victim.team,cfg,true)&&Vector2.Distance(u.position,victim.position)<=F(cfg,"area")){Heal(u,F(cfg["fields"],"Ihp2",175));u.mana=Mathf.Min(u.maxMana,u.mana+F(cfg["fields"],"Imp2",50));ApplyEffectData(u,new JObject{["id"]="A08A",["name"]="Лунное благословение",["kind"]="buff",["armor"]=F(cfg["fields"],"Idef",6),["duration"]=F(cfg,"duration",6)},victim.team);PulseAt(u.position,1,Color.magenta,"",1,"night:A08A:buff");}NightBlessings++;}
    void TickNight(float dt){using(var snapshot035_1=SimulationBuffers035.Take(NightZones))foreach(var zone in snapshot035_1){zone.age+=dt;while(zone.next<=11&&zone.age+.00001f>=zone.next){zone.next+=2;var cfg=Abilities["A07T"];using(var snapshot035_2=SimulationBuffers035.Take(Units))foreach(var u in snapshot035_2)if(Valid(u,zone.team,cfg,false)&&Vector2.Distance(u.position,zone.point)<=F(cfg,"area")){DamageUnit(u,F(cfg,"power"),zone.team);PulseAt(u.position,1,Color.magenta,"",NightStarfallHitLife,"night:night_starfall_hit:effect");}using(var snapshot035_3=SimulationBuffers035.Take(Huts))foreach(var h in snapshot035_3)if(h.team!=zone.team&&h.paid&&h.hp>0&&Vector2.Distance(h.position,zone.point)<=F(cfg,"area")){DamageHut(h,F(cfg,"power")*.4f,"magic",zone.team,true);PulseAt(h.position,2,Color.magenta,"",NightStarfallHitLife,"night:night_starfall_hit:effect");}if(Vector2.Distance(CastlePosition(1-zone.team),zone.point)<=F(cfg,"area"))DamageCastle(1-zone.team,F(cfg,"power")*.4f,"magic",true);}if(zone.age>=11)NightZones.Remove(zone);}using(var snapshot035_4=SimulationBuffers035.Take(Units))foreach(var u in snapshot035_4)if(u.hp>0)TickNightStealth(u,dt);}
    void NightBarrage(Unit source,Weapon weapon,int primary){foreach(string id in source.abilities){var cfg=Abilities[id];if((bool?)cfg?["projectile_barrage"]!=true||id!="A03N"&&id!="A03O")continue;var mask=(JObject)cfg.DeepClone();mask["physical_control"]=true;var targets=Units.Where(u=>u.id!=primary&&Valid(u,source.team,mask,false)&&Vector2.Distance(u.position,source.position)<=F(cfg,"area")).OrderBy(u=>(u.position-source.position).sqrMagnitude).Take(Mathf.Max(0,(int)F(cfg,"count")-1)).ToArray();foreach(var target in targets){var w=weapon.Copy();w.missile="night:"+id;w.speed=F(cfg["fields"],"amsp")/30;w.homing=F(cfg["fields"],"amho",1)>0;w.arc=F(cfg["fields"],"amac");var shot=AddShot(source.team,source.kind,source.id,target.id,source.position,target.position,((source.attackOverride>=0?source.attackOverride:weapon.damage)+source.abilities.Sum(key=>(string)Abilities[key]?["kind"]=="self_passive"?F(Abilities[key],"damage_bonus"):0)+ChaosSealBonus(source)+NightFlat(source))*Mathf.Max(0,1+Stat(source,"damage"))*Mathf.Max(0,1+source.auraDamage+source.auraDamageNegative)*InventoryDamage(source),w,0,3);shot.nightSecondary=true;NightBarrages++;}break;}}
    void NightKilled(Unit killer,Unit victim){if(killer==null||ElementalIllusion(killer)||killer.team==victim.team||!((string)Lines[victim.kind].stats["unit_types"]??"").ToLowerInvariant().Contains("sapper"))return;if(Lines[victim.kind].unit=="e00A"&&killer.hp>0)DamageUnit(killer,350,victim.team,"chaos",false,false,victim);if(killer.hp>0&&new[]{"e00A","e00B"}.Contains(Lines[killer.kind].unit))Heal(killer,killer.maxHp*(Lines[killer.kind].unit=="e00A"?.2f:.14f));}
    void NightDeathAspect(Unit victim){if(!TeamNight[victim.team]||Aspects[victim.team]!=1||Invulnerable(victim)||Hidden(victim)||ElementalIllusion(victim)||victim.summoned||victim.spellBorn||victim.noBounty)return;var heir=Units.Where(u=>NightFighter(u,victim.team)&&Vector2.Distance(u.position,victim.position)<=600f/30).OrderBy(u=>(u.position-victim.position).sqrMagnitude).FirstOrDefault();if(heir!=null){heir.nightVengeance=Mathf.Min(10,heir.nightVengeance+1);heir.nightVengeanceTeam=heir.team;PulseAt(heir.position,1,Color.magenta,"Месть леса",.8f,"night:night_vengeance:trigger");}}
    public float NightFlat(Unit u){if(u.nightVengeanceTeam!=u.team)u.nightVengeance=0;return u.nightVengeance*4;}
    public float NightEvasion(Unit u)=>TeamNight[u.team]&&Aspects[u.team]==0&&NightFighter(u,u.team)?Mathf.Max(u.evasion,Mathf.Min(.4f,u.evasion+.1f)):u.evasion;
    JToken NightWindProfile(Unit u)=>AbilityView035.Get(u,Abilities).wind;
    void NightEnterStealth(Unit u,JToken cfg){if(u.mana<F(cfg,"mana"))return;u.mana-=F(cfg,"mana");u.nightFade=F(cfg,"fade");u.nightStealth=F(cfg,"duration",200);u.nightInvisible=u.nightFade<=0;u.nightSpeed=F(cfg,"speed");u.nightBonus=F(cfg,"bonus");u.combatTarget=-1;u.nightQuiet=0;}
    void NightCreated(Unit u){if(ElementalIllusion(u))return;var cfg=NightWindProfile(u);if(cfg!=null)NightEnterStealth(u,cfg);}
    public void NightReveal(Unit u){u.nightInvisible=false;u.nightStealth=u.nightFade=u.nightSpeed=u.nightQuiet=0;}
    float NightOpening(Unit u){float bonus=u.nightInvisible?u.nightBonus:0;if(u.nightStealth>0)NightReveal(u);return bonus;}
    void TickNightStealth(Unit u,float dt){var cfg=NightWindProfile(u);if(cfg==null||ElementalIllusion(u))return;if(u.nightStealth>0){u.nightStealth-=dt;u.nightFade=Mathf.Max(0,u.nightFade-dt);u.nightInvisible=u.nightFade<=0;if(u.nightStealth<=0)NightReveal(u);return;}bool busy=u.strikeLeft>=0||u.castLeft>=0||u.cooldown>0||u.stun>0||Disabled(u)||Silenced(u)||FindUnit(u.combatTarget) is Unit target&&Vector2.Distance(u.position,target.position)<=26.6667f||Units.Any(v=>v.hp>0&&v.team!=u.team&&v.combatTarget==u.id);u.nightQuiet=busy?0:u.nightQuiet+dt;if(u.nightQuiet>=2)NightEnterStealth(u,cfg);}
    public bool NightCanDetect(int team,Unit target){if(target.pandaSplit)return false;if(!target.nightInvisible||target.team==team||ElvenReveals(target,team))return true;foreach(var u in Units)if(u.hp>0&&u.team==team&&u.abilities.Any(id=>(string)Abilities[id]?["code"]=="Atru"&&Vector2.Distance(u.position,target.position)<=Mathf.Max(F(Abilities[id],"range"),F(Abilities[id],"area"))))return true;return Huts.Any(h=>h.paid&&h.hp>0&&h.team==team&&Lines[h.kind].abilities.Any(id=>(string)Abilities[id]?["code"]=="Atru"&&Vector2.Distance(h.position,target.position)<=Mathf.Max(F(Abilities[id],"range"),F(Abilities[id],"area"))));}
    Unit NightHunt(Unit source)=>Units.Where(u=>u.team!=source.team&&u.hp>0&&!Invulnerable(u)&&!Hidden(u)&&NightCanDetect(source.team,u)&&!Flying(u)&&u.maxMana>1&&!Ethereal(u)&&!u.effects.Any(e=>e.left>0&&(bool?)e.config?["untargetable"]==true)&&WeaponFor(source,u)!=null).OrderBy(u=>(u.position-source.position).sqrMagnitude).FirstOrDefault();
    bool TickNightHunt(Unit u,float dt){if(!u.nightInvisible)return false;var target=NightHunt(u);if(target==null)return false;u.combatTarget=target.id;u.onRoad=true;var w=WeaponFor(u,target);var delta=target.position-u.position;u.direction=delta.normalized;float reach=w.range+F(Lines[target.kind].stats,"collision")+F(Lines[u.kind].stats,"collision");if(delta.magnitude<=reach){if(u.cooldown<=0)BeginAttack(u,w,target.id);u.pose=u.attackPoseLeft>0?"Attack":"Stand";}else {var destination=BuilderWaypoint(u.position,target.position);u.position=Vector2.MoveTowards(u.position,destination,MoveSpeed(u)*dt);u.pose="Walk";}return true;}
    public void NightBounce(Shot shot){var pattern=shot.weapon?.pattern;if((string)pattern?["type"]!="bounce")return;int remaining=shot.nightRemaining<0?(int)F(pattern,"count")-1:shot.nightRemaining-1;if(remaining<=0)return;var seen=new HashSet<int>(shot.nightSeen??Array.Empty<int>());seen.Add(shot.target);var next=new List<Tuple<int,Vector2>>();foreach(var u in Units)if(u.team!=shot.team&&u.hp>0&&!seen.Contains(u.id)&&!Invulnerable(u)&&!Hidden(u)&&!Flying(u)&&NightCanDetect(shot.team,u))next.Add(Tuple.Create(u.id,u.position));if(((string)pattern["targets"]??"").Contains("structure")){foreach(var h in Huts)if(h.paid&&h.hp>0&&h.team!=shot.team&&!seen.Contains(HutTarget(h)))next.Add(Tuple.Create(HutTarget(h),h.position));if(!seen.Contains(-1))next.Add(Tuple.Create(-1,CastlePosition(1-shot.team)));}var target=next.Where(v=>Vector2.Distance(v.Item2,shot.end)<=F(pattern,"radius")).OrderBy(v=>(v.Item2-shot.end).sqrMagnitude).FirstOrDefault();if(target==null)return;var child=AddShot(shot.team,shot.line,shot.sourceId,target.Item1,shot.end,target.Item2,shot.damage*(1-F(pattern,"loss")),shot.weapon,0,3);child.nightSeen=seen.ToArray();child.nightRemaining=remaining;}
}
}
